changeSet.sql:
CREATE TABLE campaign_token_usage (
character_hash VARCHAR(64) NOT NULL,
user_hash VARCHAR(64) NOT NULL,
total_tokens BIGINT NOT NULL DEFAULT 0,
month_tokens BIGINT NOT NULL DEFAULT 0,
last_reset_month VARCHAR(7) NOT NULL,
updated TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),
CONSTRAINT pk_campaign_token_usage PRIMARY KEY (character_hash)
);
CREATE INDEX idx_campaign_token_usage_user_hash ON campaign_token_usage (user_hash);
